import{_ as o,a0 as d,w as m,s as p,I as n,x as t,a1 as l,A as r,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸 | LCTT x X-CMD","titleTemplate":false,"description":"elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210826 Elementary OS 6 Odin Review - Late Arrival but a Solid One","title":"elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸","tag":"202109","desc":""},"relativePath":"202109/20210826 Elementary OS 6 Odin Review - Late Arrival but a Solid One.md","filePath":"[post].md"}'),s={name:"202109/20210826 Elementary OS 6 Odin Review - Late Arrival but a Solid One.md"};function u(O,e,S,y,f,b){const a=d("Link");return m(),p("div",null,[e[21]||(e[21]=n("h1",{id:"elementary-os-6-odin-評測-遲到的新版本-但也實至名歸",tabindex:"-1"},[t("elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸 "),n("a",{class:"header-anchor",href:"#elementary-os-6-odin-評測-遲到的新版本-但也實至名歸","aria-label":"Permalink to “elementary OS 6 Odin 評測：遲到的新版本，但也實至名歸”"},"​")],-1)),e[22]||(e[22]=n("blockquote",null,[n("p",null,"這篇 elementary OS 6 的評測將為你呈現該系統在舊款測試設備上的表現。")],-1)),e[23]||(e[23]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/01/095116zk73wcc4g5clnvq8.jpg",alt:""})],-1)),e[24]||(e[24]=n("p",null,"elementary OS 的粉絲們焦急等待 elementary OS 6 Odin 發佈已經將近兩年了。如此焦急的原因，主要在於早期版本 elementary OS 5.1 的內核和軟件包在 2021 年來説過於陳舊。而且，這一舊版本基於 Ubuntu 18.04 LTS 構建。因此，用户都急切地等待着基於 Ubuntu 20.04 LTS 的全新版本 —— 最重要的是，Ubutnu 20.04 LTS 已經發布一年，接下來也將有下一個 LTS 版本發佈。",-1)),e[25]||(e[25]=n("p",null,"你應該也明白的，過長的等待時間，很可能導致用户跳槽到其他發行版。",-1)),n("p",null,[e[1]||(e[1]=t("但即便如此，新版本終於還是 ",-1)),l(a,{href:"https://blog.elementary.io/elementary-os-6-odin-released/"},{default:r(()=>[...e[0]||(e[0]=[t("在 8 月發佈了",-1)])]),_:1}),e[2]||(e[2]=t("，它在用户和粉絲羣體很受歡迎。",-1))]),e[26]||(e[26]=i('<p>於是，我在一週前為一台舊設備（我知道新設備的體驗會更好）安裝了 elementary OS 6 Odin，下面就是測評。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/elementary-OS-6-ODIN-Desktop-1024x576.jpeg" alt="elementary OS 6 Odin 的桌面"></p><h3 id="elementary-os-6-odin-測評" tabindex="-1">elementary OS 6 Odin 測評 <a class="header-anchor" href="#elementary-os-6-odin-測評" aria-label="Permalink to “elementary OS 6 Odin 測評”">​</a></h3><p>測試設備：</p><ul><li>CPU – Intel Core i3，4 GB 運行內存</li><li>硬盤 – SSD 固態硬盤</li><li>顯卡 – Nvidia GeForce（340）</li></ul><h4 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h4><p>在這一版本中，elementary 團隊針對他們自制的 elementary OS 安裝器做了易用性優化。新安裝器減少了安裝前的準備步驟，雖然它還是需要依賴 GParted 進行分區操作（當然 GParted 本身是一款不錯的工具）。</p><p>在前述測試設備中，安裝過程大約花費了 10 分鐘，沒有任何報錯。安裝完之後，GRUB 也正常更新，沒有任何意外。這是一個安裝在老式 BIOS 上多引導系統。</p><h4 id="初見印象" tabindex="-1">初見印象 <a class="header-anchor" href="#初見印象" aria-label="Permalink to “初見印象”">​</a></h4><p>如果你剛聽説 elementary OS 和 Pantheon 桌面，或者從其他傳統的菜單型桌面環境遷移過來，你可能需要一兩天時間來適應這款桌面。當然，如果你已經是 elementary OS 的老用户的話，那麼你將獲得一致的體驗，外加性能和外觀的優化。</p>',10)),n("p",null,[e[4]||(e[4]=t("你應該可以察覺到一些明顯可見的 ",-1)),l(a,{href:"https://www.debugpoint.com/2021/08/elementary-os-6/"},{default:r(()=>[...e[3]||(e[3]=[t("elementary OS 6 的新特性",-1)])]),_:1}),e[5]||(e[5]=t("，像是強調色、原生暗黑模式，以及一組不錯的新壁紙。",-1))]),e[27]||(e[27]=i('<h4 id="穩定性與性能" tabindex="-1">穩定性與性能 <a class="header-anchor" href="#穩定性與性能" aria-label="Permalink to “穩定性與性能”">​</a></h4><p>我已經使用 elementary OS 6 Odin 超過一週的時間。在日常使用後，我只能説，它很穩定，沒有突然的崩潰和意外。其他（通過 <code>apt</code> 單獨安裝的）額外軟件也運作正常，性能也沒有降低。</p><p>在近乎閒置的情況下，CPU 使用率處在 5%-10% 之間，內存佔用約為 900 MB。CPU / 內存的消耗主要分配在 Gala（Pantheon 的窗口管理器）、Wingpanel（頂欄）和應用中心。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/System-performance-of-elementary-OS-6.jpeg" alt="elementary OS 6 的系統性能"></p><p>考慮到系統的視覺效果，我認為這些佔用數據也十分合理。不過，當你打開更多軟件，例如 LibreOffice、Chrome、Kdenlive 之後，消耗的資源肯定會更多。</p><h4 id="應用程序與應用中心" tabindex="-1">應用程序與應用中心 <a class="header-anchor" href="#應用程序與應用中心" aria-label="Permalink to “應用程序與應用中心”">​</a></h4><p>elementary OS 的應用程序列表經過精選，幾乎所有類型的軟件都可以從應用中心獲取，包括 Flatpak 應用。不過，elementary OS 默認並沒有預裝一些重要的應用程序，像是 Firefox、LibreOffice、Torrent 客户端、硬盤分區工具、照片編輯器之類 —— 這些重要的程序需要在安裝系統後再自行安裝。我認為預裝軟件這一塊有很大的改進空間。</p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>在這一週的測試中，我也多次遇到了一個 bug，Wi-Fi 有時會突然斷開，不過這完全是上游 Ubuntu 20.04 的問題 —— 多年以來，它一直有奇怪的 Wi-Fi 問題。拋開這個問題，elementary OS 確實是一款穩定、優秀的 Linux 發行版。如果 elementary OS 有滾動更新的版本，也許會更好。因此，這是一款值得推薦的發行版，尤其適合那些從 macOS 遷移過來的人。</p><hr>',10)),n("p",null,[e[7]||(e[7]=t("via: ",-1)),l(a,{href:"https://www.debugpoint.com/2021/08/elementary-os-6-odin-review/"},{default:r(()=>[...e[6]||(e[6]=[t("https://www.debugpoint.com/2021/08/elementary-os-6-odin-review/",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("作者：",-1)),l(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:r(()=>[...e[8]||(e[8]=[t("Arindam",-1)])]),_:1}),e[13]||(e[13]=t(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),l(a,{href:"https://github.com/imgradeone"},{default:r(()=>[...e[10]||(e[10]=[t("imgradeone",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[18]||(e[18]=t("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:r(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const x=o(s,[["render",u]]);export{g as __pageData,x as default};
